        mut self,
        handler: impl Fn(&SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_submit = Some(Rc::new(handler));
        self
    }
    /// Refine the default styles while retaining editing and focus behavior.
    pub fn style_with_state(
        mut self,
